import fs from 'node:fs';
import {Worker,isMainThread,workerData,parentPort} from 'node:worker_threads';
import {coreStand} from '../../tests/harness/core-stand.mjs';
import {modelSpec} from '../../src/core/models.ts';
import {guardPosture} from '../../src/core/skills/guard.ts';
import {LAB_PRESETS} from '../../src/lab/scenarios.ts';
import {labActor} from '../../src/lab/actor.ts';
import {recoveryMeasurement} from '../../src/core/control/recovery-measurement.ts';
import {startStance} from '../../src/lab/stance-mode.ts';
if(isMainThread){
 const results=await Promise.all([270].map(degrees=>new Promise((resolve,reject)=>{const w=new Worker(new URL(import.meta.url),{workerData:{degrees}});w.on('message',resolve);w.on('error',reject);})));
 fs.writeFileSync('.review/lab-research-rise/support-loop.json',JSON.stringify(results,null,2)+'\n');console.log(JSON.stringify(results.map(({samples,...r})=>r)));
}else{
 const spec=modelSpec('workshop-fighter'),stand=await coreStand(spec,{engine:'rapier-coordinate',groundSize:40,posture:guardPosture(spec)});
 const mind={...LAB_PRESETS.script.config,subs:[{kind:'research-rise'}]},stance=startStance(labActor(stand.built,stand.world,{mind})),samples=[];
 const measure=recoveryMeasurement(stand.built,()=>stance.body.observe());
 try{
  stand.world.step(240);stance.shove(60,workerData.degrees);stand.world.step(24);stance.shove(60,workerData.degrees);
  let first=null,maxHelp=0;
  for(let i=0;i<7200;i++){
   stand.world.step();if(stance.body.down)first??=stand.world.time;
   maxHelp=Math.max(maxHelp,stance.body.assist.meter.force,stance.body.assist.meter.moment);
   if(i%6===0){const m=measure(),o=m.observation,s=stance.body.state.mind.subs[0];samples.push({rootUp:m.rootUp,soleUp:m.soleUp,ready:m.ready,loads:Object.fromEntries(o.contacts.filter(c=>c.fixed!==null&&c.impulse>0).map(c=>[c.segment,c.impulse/stand.world.dt])),time:stand.world.time,down:stance.body.down,height:o.height,controller:stance.body.has,attempts:s.attempts,completed:s.completed,phase:s.policy.phase,reference:s.policy.reference,exhaustedAt:s.exhaustedAt});}
  }
  const s=stance.body.state.mind.subs[0];parentPort.postMessage({...workerData,first,maxHelp,attempts:s.attempts,completed:s.completed,down:stance.body.down,samples});
 }finally{stance.dispose();stand.dispose();}
}

