import fs from 'node:fs';
import assert from 'node:assert/strict';
import {gunzipSync} from 'node:zlib';
import {deserialize} from 'node:v8';
import {Quaternion,Vector3} from '@babylonjs/core/Maths/math.vector.js';
import {acceptanceEnvironment} from '../../.tools/stand-up-frozen/research/stand-up-acceptance.mjs';
import {standUpKinematics,solveStandUpPose} from './clear-ik.mjs';
const dir='.review/stand-up-held-kneel/',manifest=JSON.parse(fs.readFileSync('.tools/stand-up-frozen/research/stand-up-acceptance/cases.json'));
const trace=deserialize(gunzipSync(fs.readFileSync(dir+'tripod.trace.gz'))),c=manifest.cases[9],e=await acceptanceEnvironment(c.configuration),prefixSteps=640;
try{
 e.restore(gunzipSync(fs.readFileSync('.tools/stand-up-frozen/research/stand-up-acceptance/'+c.file)));assert.deepEqual(e.observe(),trace.initial);
 for(let i=0;i<prefixSteps;i++)assert.deepEqual(e.step(trace.rows[i].action,{automaticHandover:true}),trace.rows[i]);
 const o=e.observe(),model=standUpKinematics({stand:e.stand,observe:e.observe,stance:{body:e.body},metadata:e.identity});
 model.retained=model.retained.map(r=>({...r,target:r.target.map((v,i)=>i===1?Math.max(0,v):v)}));
 const goals=model.retained.map(r=>({...r,rotation:new Quaternion(...o.segments.find(s=>s.name===r.name).rotation)}));
 const direction=model.targetRotation.multiply(Quaternion.Inverse(e.stand.built.segments.get('foot.left').rest)),across=new Vector3(1,0,0).applyRotationQuaternion(direction).asArray(),front=new Vector3(0,0,1).applyRotationQuaternion(direction).asArray();
 const candidates=[];
 for(const lateral of [-.45])for(const forward of [.2])for(const toe of [0,-.7]){
  const target=model.target.map((v,k)=>v+lateral*across[k]+forward*front[k]);
