import {Quaternion,Vector3} from '@babylonjs/core/Maths/math.vector.js';
import {motionAxesToRef} from '../../src/core/build/joint-state.ts';
import {spinBetweenToRef} from '../../src/core/math/turn.ts';
import {contactPolicy as posePolicy} from './policy.mjs';

function solve(A,b){
 const rows=A.map((r,i)=>[...r,b[i]]),n=b.length;
 for(let k=0;k<n;k++){
  let pivot=k;for(let i=k+1;i<n;i++)if(Math.abs(rows[i][k])>Math.abs(rows[pivot][k]))pivot=i;
  [rows[k],rows[pivot]]=[rows[pivot],rows[k]];if(Math.abs(rows[k][k])<1e-14)throw Error('singular anchored-hand solve');
  for(let i=k+1;i<n;i++){const f=rows[i][k]/rows[k][k];for(let j=k;j<=n;j++)rows[i][j]-=f*rows[k][j];}
 }
 const x=new Array(n).fill(0);for(let i=n-1;i>=0;i--){let r=rows[i][n];for(let j=i+1;j<n;j++)r-=rows[i][j]*x[j];x[i]=r/rows[i][i];}return x;
}

// A measured hand contact is a muscle target, never a physics pin or applied force.
export function contactPolicy(args){
 const {model,parameters:p}=args,base=posePolicy(args),state={base:base.state,phase:'retain palms',anchors:null,errors:[],angularErrors:[],residual:[]};
 const groups=[];let offset=0;
 for(const joint of model.joints){groups.push({joint,offset});offset+=joint.dofs.length;}
 const policy=o=>{
  const action=base(o);state.phase=base.state.phase;
  if(!p.anchorGain)return action;
  state.anchors??=['left','right'].map(side=>{
   const name='hand.'+side,hand=o.segments.find(s=>s.name===name),c=o.contacts.find(c=>c.segment===name&&c.fixed!==null&&c.impulse>0);
   if(!c)throw Error('initial hand anchor requires actual loaded contact');
   const local=new Vector3(...c.point).subtractInPlace(new Vector3(...hand.position)).applyRotationQuaternionToRef(Quaternion.Inverse(new Quaternion(...hand.rotation)),new Vector3()).asArray();
   return {side,name,local,target:[...c.point],rotation:[...hand.rotation]};
  });
  const byName=new Map(o.segments.map(s=>[s.name,s])),lever=p.anchorOrientation??0;
  for(const [anchorIndex,a] of state.anchors.entries()){
   const hand=byName.get(a.name),q=new Quaternion(...hand.rotation),at=new Vector3(...a.local).applyRotationQuaternionToRef(q,new Vector3()).addInPlaceFromFloats(...hand.position);
   const pointVelocity=Vector3.Cross(new Vector3(...hand.spin),at.subtract(new Vector3(...hand.centre))).addInPlaceFromFloats(...hand.velocity);
   const error=new Vector3(...a.target).subtractInPlace(at),turn=spinBetweenToRef(q,new Quaternion(...a.rotation),1,new Vector3());
   state.errors[anchorIndex]=error.length();state.angularErrors[anchorIndex]=turn.length();
   const want=error.scale(p.anchorGain).subtractInPlace(pointVelocity).asArray();
   if(lever)want.push(...turn.scale(p.anchorGain).subtractInPlaceFromFloats(...hand.spin).scaleInPlace(lever).asArray());
   const columns=[],indices=[];
   for(const {joint,offset} of groups){
    if(!/^(shoulder|elbow|wrist)\./.test(joint.spec.name)||!joint.descendants.includes(a.name))continue;
    const parent=byName.get(joint.parent),rotation=new Quaternion(...parent.rotation).multiply(new Quaternion(...joint.parentRestInverse));
    const pivot=new Vector3(...joint.pivot).applyRotationQuaternionToRef(new Quaternion(...parent.rotation),new Vector3()).addInPlaceFromFloats(...parent.position),arm=at.subtract(pivot);
    const axes=motionAxesToRef(joint,o.joints.slice(offset,offset+joint.dofs.length).map(j=>j.angle),[]);
    for(let k=0;k<axes.length;k++){
     const axis=new Vector3(...axes[k]).applyRotationQuaternionToRef(rotation,new Vector3()),column=Vector3.Cross(axis,arm).asArray();
     if(lever)column.push(...axis.scale(lever).asArray());columns.push(column);indices.push(offset+k);
    }
   }
   // The measured point velocity includes root and spine motion. Only arm motor speeds are changed.
   const rhs=want.map((v,k)=>v-columns.reduce((sum,c,j)=>sum+c[k]*(action.velocity[indices[j]]-o.joints[indices[j]].speed),0));
   const A=want.map((_,k)=>want.map((_,l)=>columns.reduce((sum,c)=>sum+c[k]*c[l],0)+(k===l?p.anchorDamping*p.anchorDamping:0)));
   const y=solve(A,rhs),correction=columns.map(c=>c.reduce((sum,v,k)=>sum+v*y[k],0));
   state.residual[anchorIndex]=Math.sqrt(rhs.reduce((sum,v,k)=>sum+(v-columns.reduce((n,c,j)=>n+c[k]*correction[j],0))**2,0));
   indices.forEach((i,j)=>{action.velocity[i]=Math.max(-p.anchorSpeed,Math.min(p.anchorSpeed,action.velocity[i]+correction[j]));});
  }
  return action;
 };policy.state=state;return policy;
}

