 return {step:start+k+1,time:r.result.elapsed,sinceStart:r.result.elapsed-first,height:o.height,rootUp:r.rootUp,centre:o.centre,soleUp:r.soleUp,
  outside:nearest?Math.hypot(nearest[0]-o.centre[0],nearest[1]-o.centre[2]):null,
