import {contactPolicy as risePolicy} from './pike-rise-policy.mjs';

// Only the trajectory clock is slowed; measured body motion and muscle limits remain real.
export function contactPolicy(args){
 const p=args.parameters,base=risePolicy(args),state={base:base.state,phase:'governed prepare',clock:null,lastTime:null,rate:1,capacityFraction:0,speedError:0,previous:null};
 const indices=args.model.channels.flatMap((c,i)=>p.governParts==='wrists'?(/^wrist\./.test(c.name)?[i]:[]):(/^(wrist\.|lumbar |thoracic )/.test(c.name)?[i]:[]));
 const policy=o=>{
  state.clock??=o.time;
  const dt=state.lastTime===null?0:o.time-state.lastTime;state.lastTime=o.time;
  state.capacityFraction=Math.max(...indices.map(i=>{const j=o.joints[i],capacity=j.effort>=0?j.positive:j.negative;return capacity?Math.abs(j.effort)/capacity:0;}));
