import {Quaternion,Vector3} from '@babylonjs/core/Maths/math.vector.js';
import {motionAxesToRef,turningToRef,ratesToRef} from '../../src/core/build/joint-state.ts';
import {spinBetweenToRef} from '../../src/core/math/turn.ts';
import {contactPolicy as posePolicy} from './policy.mjs';

function solve(A,b){
 const a=A.map((r,i)=>[...r,b[i]]),n=b.length;
 for(let k=0;k<n;k++){
  let pivot=k;for(let i=k+1;i<n;i++)if(Math.abs(a[i][k])>Math.abs(a[pivot][k]))pivot=i;
  [a[k],a[pivot]]=[a[pivot],a[k]];if(Math.abs(a[k][k])<1e-14)throw Error('singular upper-body solve');
  for(let i=k+1;i<n;i++){const f=a[i][k]/a[k][k];for(let j=k;j<=n;j++)a[i][j]-=f*a[k][j];}
 }
 const x=new Array(n).fill(0);for(let i=n-1;i>=0;i--){let v=a[i][n];for(let j=i+1;j<n;j++)v-=a[i][j]*x[j];x[i]=v/a[i][i];}return x;
}

// The shared spine and both arms coordinate two measured palm targets through muscles.
export function contactPolicy(args){
 const {model,parameters:p}=args,base=posePolicy(args),state={base:base.state,phase:'upper-body support',anchors:null,errors:[],angularErrors:[],residual:0,bounded:0};
 const groups=[];let offset=0;for(const joint of model.joints){groups.push({joint,offset});offset+=joint.dofs.length;}
 const policy=o=>{
  const action=base(o);state.phase=base.state.phase;
  state.anchors??=['left','right'].map(side=>{
   const name='hand.'+side,hand=o.segments.find(s=>s.name===name),c=o.contacts.find(c=>c.segment===name&&c.fixed!==null&&c.impulse>0);
   if(!c)throw Error('a palm target starts at a loaded contact');
   const local=new Vector3(...c.point).subtractInPlace(new Vector3(...hand.position)).applyRotationQuaternionToRef(Quaternion.Inverse(new Quaternion(...hand.rotation)),new Vector3()).asArray();
   return {name,local,target:[...c.point],rotation:[...hand.rotation]};
  });
  const byName=new Map(o.segments.map(s=>[s.name,s])),lever=p.anchorOrientation??0,want=[];
  const hands=state.anchors.map((a,i)=>{
   const hand=byName.get(a.name),q=new Quaternion(...hand.rotation),at=new Vector3(...a.local).applyRotationQuaternionToRef(q,new Vector3()).addInPlaceFromFloats(...hand.position);
   const velocity=Vector3.Cross(new Vector3(...hand.spin),at.subtract(new Vector3(...hand.centre))).addInPlaceFromFloats(...hand.velocity),error=new Vector3(...a.target).subtractInPlace(at),turn=spinBetweenToRef(q,new Quaternion(...a.rotation),1,new Vector3());
   state.errors[i]=error.length();state.angularErrors[i]=turn.length();
   want.push(...error.scale(p.anchorGain).subtractInPlace(velocity).asArray());
   if(lever)want.push(...turn.scale(p.anchorGain).subtractInPlace(new Vector3(...hand.spin)).scaleInPlace(lever).asArray());
   return {name:a.name,at};
  });
  const columns=[],indices=[],baseRates=[],jointGroups=[],weights=[];
  for(const {joint,offset} of groups){
   if(!hands.some(h=>joint.descendants.includes(h.name)))continue;
   if(!p.sharedSpine&&!/^(shoulder|elbow|wrist)\./.test(joint.spec.name))continue;
   const n=joint.dofs.length,angles=o.joints.slice(offset,offset+n).map(j=>j.angle),parent=byName.get(joint.parent),rotation=new Quaternion(...parent.rotation).multiply(new Quaternion(...joint.parentRestInverse));
   const pivot=new Vector3(...joint.pivot).applyRotationQuaternionToRef(new Quaternion(...parent.rotation),new Vector3()).addInPlaceFromFloats(...parent.position),axes=motionAxesToRef(joint,angles,[]),T=turningToRef(joint,angles,[]),rates=ratesToRef(joint,angles,action.velocity.slice(offset,offset+n),[]);
   const motorColumns=axes.map(axis=>{
    const v=new Vector3(...axis).applyRotationQuaternionToRef(rotation,new Vector3());
    return hands.flatMap(h=>joint.descendants.includes(h.name)?[...Vector3.Cross(v,h.at.subtract(pivot)).asArray(),...(lever?v.scale(lever).asArray():[])]:new Array(lever?6:3).fill(0));
   });
   const first=columns.length;
   for(let k=0;k<n;k++){columns.push(want.map((_,r)=>motorColumns.reduce((sum,c,j)=>sum+c[r]*T[j][k],0)));indices.push(offset+k);baseRates.push(rates[k]);weights.push(joint.spec.name.startsWith('wrist.')?p.wristWeight:1);}
   jointGroups.push({offset,first,T});
  }
  const target=want.map((v,k)=>v+columns.reduce((sum,c,j)=>sum+c[k]*(p.anchorMode==='additive'?baseRates[j]:o.joints[indices[j]].rate),0));
  const fixed=new Map(),rates=[...baseRates],bounds=indices.map(i=>[Math.max(-p.anchorSpeed,(model.channels[i].min-o.joints[i].angle)/p.boundSeconds),Math.min(p.anchorSpeed,(model.channels[i].max-o.joints[i].angle)/p.boundSeconds)]);
  for(let iteration=0;iteration<=indices.length;iteration++){
   const free=indices.map((_,j)=>j).filter(j=>!fixed.has(j));
   const rhs=target.map((v,k)=>v-columns.reduce((sum,c,j)=>sum+c[k]*(fixed.has(j)?fixed.get(j):baseRates[j]),0));
   const A=target.map((_,k)=>target.map((_,l)=>free.reduce((sum,j)=>sum+weights[j]*columns[j][k]*columns[j][l],0)+(k===l?p.anchorDamping*p.anchorDamping:0)));
   const y=solve(A,rhs);for(const j of free)rates[j]=baseRates[j]+weights[j]*columns[j].reduce((sum,v,k)=>sum+v*y[k],0);for(const [j,v] of fixed)rates[j]=v;
   let selected=-1,excess=0;for(const j of free){const d=Math.max(bounds[j][0]-rates[j],rates[j]-bounds[j][1]);if(d>excess){excess=d;selected=j;}}
   if(selected<0)break;fixed.set(selected,Math.max(bounds[selected][0],Math.min(bounds[selected][1],rates[selected])));
  }
  state.bounded=fixed.size;state.residual=Math.sqrt(target.reduce((sum,v,k)=>sum+(v-columns.reduce((n,c,j)=>n+c[k]*rates[j],0))**2,0));
  for(const {offset,first,T} of jointGroups)for(let k=0;k<T.length;k++)action.velocity[offset+k]=T[k].reduce((sum,v,j)=>sum+v*rates[first+j],0);
  return action;
 };policy.state=state;return policy;
}

