  const hand=byName.get(name),contact=o.contacts.find(c=>c.segment===name&&c.fixed!==null&&c.impulse>0),at=new Vector3(...contact.point);
  const local=at.subtract(new Vector3(...hand.position)).applyRotationQuaternionToRef(Quaternion.Inverse(new Quaternion(...hand.rotation)),new Vector3()).asArray();
