  return {side,sustained,best:best??null};
 });
 return {path,traceSha256:t.traceSha256,harness:t.identity.harness,engine:t.identity.engine,hz:t.identity.hz,balance:t.identity.balance,result:t.result,bySide};
});
const result={screen:'Diagnostic only: sole-up > 0.8 and upward floor contact load > 20 N, sustained for at least 12 steps. It does not establish sole clearance, support margin or standing.',results};
