import {Quaternion,Vector3} from '@babylonjs/core/Maths/math.vector.js';
import {turningToRef} from '../../src/core/build/joint-state.ts';
import {contactPolicy as footPolicy} from '../stand-up-foot-first/policy.mjs';

// Muscle-limited hip flexion transfers away from the extended-hip, inverted-pelvis trap.
export function contactPolicy({model,parameters:p}){
 const base=footPolicy({model,parameters:p});
 const state={base:base.state,phase:'place feet',loaded:false,rootUp:0,folding:false};
 const joints=[];let offset=0;for(const joint of model.joints){joints.push({joint,offset});offset+=joint.dofs.length;}
 const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
 const policy=o=>{
  const action=base(o),root=o.segments.find(s=>s.name==='lowerTrunk');
  const q=new Quaternion(...root.rotation).multiply(Quaternion.Inverse(new Quaternion(...model.rootRest)));
  state.rootUp=new Vector3(0,1,0).applyRotationQuaternionToRef(q,new Vector3()).y;
  state.loaded||=base.state.loads.some((load,i)=>load>20&&base.state.soleUp[i]>.8);
  state.folding=p.fold&&(p.immediate||state.loaded)&&state.rootUp<p.untilUp;
  state.phase=state.folding?'hip transfer':'place feet';
  for(const {joint,offset}of joints){
   const n=joint.dofs.length,isHip=joint.spec.name.startsWith('hip.'),isSpine=['lumbar','thoracic'].includes(joint.spec.name);
   if(!(state.folding&&(isHip||p.spine&&isSpine)))continue;
   const angles=o.joints.slice(offset,offset+n).map(j=>j.angle),T=turningToRef(joint,angles,[]);
   // Keep the other joint-angle rates measured while changing flexion in anatomical coordinates.
   const rates=o.joints.slice(offset,offset+n).map(j=>j.rate);
   for(let k=0;k<n;k++)if(model.channels[offset+k].name.endsWith(' flexion')&&!model.channels[offset+k].name.includes('lateral')){
    const c=model.channels[offset+k],goal=clamp(isHip?p.hipTarget:p.spineTarget,c.min,c.max);
    rates[k]=clamp(p.foldGain*(goal-angles[k]),-p.foldSpeed,p.foldSpeed);
   }
   for(let k=0;k<n;k++){action.activation[offset+k]=1;action.velocity[offset+k]=T[k].reduce((sum,v,j)=>sum+v*rates[j],0);}
  }
  return action;
 };policy.state=state;return policy;
}

