export function contactPolicy({model,parameters:p}){
 const base=footPolicy({model,parameters:p});
 const state={base:base.state,phase:'place feet',loaded:false,rootUp:0,folding:false};
 const joints=[];let offset=0;for(const joint of model.joints){joints.push({joint,offset});offset+=joint.dofs.length;}
 const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
 const policy=o=>{
  const action=base(o),root=o.segments.find(s=>s.name==='lowerTrunk');
