  state.rootUp=new Vector3(0,1,0).applyRotationQuaternionToRef(q,new Vector3()).y;
  const loaded=base.state.loads.some((load,i)=>load>20&&base.state.soleUp[i]>.8);
  state.loaded||=loaded;
  state.folding=p.fold&&(p.immediate||(p.currentLoad?loaded:state.loaded))&&state.rootUp<p.untilUp;
  state.phase=state.folding?'hip transfer':'place feet';
  for(const {joint,offset}of joints){
   const n=joint.dofs.length,isHip=joint.spec.name.startsWith('hip.'),isSpine=['lumbar','thoracic'].includes(joint.spec.name);
