 const rest=Object.fromEntries([...e.stand.built.segments].map(([name,s])=>[name,Quaternion.Inverse(s.rest)]));
 const weight=[...e.stand.built.segments.values()].reduce((n,s)=>n+s.rigid.mass,0)*9.81;
