 };
 const anatomy=pose=>e.channels.map(c=>clamp((pose[c.name]??0)-c.bind,c.min,c.max));
 const bilateral=pose=>Object.fromEntries(Object.entries(pose).flatMap(([name,value])=>name.includes('@')?['left','right'].map(s=>[name.replace('@',s),value]):[[name,value]]));
