  const current=observation.joints.map(j=>j.angle),controls=poses.map(p=>({...p,kind:'targets',response:.15}));
  controls.push({name:'hold',kind:'targets',angles:current.map((a,i)=>clamp(a,e.channels[i].min,e.channels[i].max)),response:.15});
