   const angles=current.map((v,i)=>{const c=e.channels[i];const delta=(side==='both'||c.name.includes('.'+side+' '))?(c.name.startsWith('hip.')&&c.name.endsWith(' flexion')?hip:c.name.startsWith('knee.')?knee:0):0;return clamp(v+delta,c.min,c.max);});
