  }
  for(const side of ['left','right','both'])for(const [shoulder,elbow]of [[.5,.5],[.5,-.5],[-.5,-.5]]){
   const angles=current.map((v,i)=>{const c=e.channels[i];const delta=(side==='both'||c.name.includes('.'+side+' '))?(c.name.startsWith('shoulder.')&&c.name.endsWith(' flexion')?shoulder:c.name.startsWith('elbow.')?elbow:0):0;return clamp(v+delta,c.min,c.max);});
   controls.push({name:`arm ${side} ${shoulder} ${elbow}`,kind:'targets',angles,response:.1});
  }
  const seen=new Set();return controls.filter(c=>{const key=JSON.stringify(c.angles);if(seen.has(key))return false;seen.add(key);return true;});
 };
 return {e,c,initial,initialObservation,standing,features,run,proposals};
}

if(!isMainThread){
 const s=await stand(workerData.caseIndex);
 parentPort.on('message',({id,x})=>{try{parentPort.postMessage({id,r:s.run(x.snapshot,x.control,x.steps)});}catch(error){parentPort.postMessage({id,r:{error:String(error.stack)}});}});
}else{
