 assert.ok(out);const revision=frozenRevision(),sourceSha256=sha(fs.readFileSync(new URL(import.meta.url))),s=await stand(caseIndex),pool=workerPool(new URL(import.meta.url),{caseIndex},3);
 const began=Date.now(),depths=[];let evaluations=0,physicalSteps=0,best,success=null;
 try{
