   const steps=Math.min(block,total-done),jobs=beam.flatMap(parent=>s.proposals(parent.o,parent.plan.at(-1)?.control).map(control=>({parent,control})));
   const candidates=await Promise.all(jobs.map(async({parent,control})=>{
    const r=await pool.evaluate({snapshot:parent.snapshot,control,steps});if(r.error)throw Error(r.error);
    evaluations++;physicalSteps+=r.steps;return {...r,plan:[...parent.plan,{control,steps:r.steps,traceSha256:r.traceSha256}]};
   }));
