   for(const r of candidates.filter(r=>r.result.handover!==null&&!r.result.failure)){
    const tail=await pool.evaluate({snapshot:r.snapshot,control:{kind:'host'},steps:361});if(tail.error)throw Error(tail.error);evaluations++;physicalSteps+=tail.steps;
    if(tail.result.success){success={...tail,plan:[...r.plan,{control:{kind:'host'},steps:tail.steps,traceSha256:tail.traceSha256}]};break;}
   }
