   for(const c of candidates){if(c.result.failure)continue;const key=[Math.floor(c.minHeight*10),Math.floor(c.rootUp*4),c.support].join(':');if((bins.get(key)??0)>=2)continue;bins.set(key,(bins.get(key)??0)+1);selected.push(c);if(selected.length===width)break;}
