      }
      for (let i = channels; i < size; i++) H[i * size + i] = 1;
      for (let r = 0; r < rows; r++) {
        let length = 0;
        for (let i = 0; i < size; i++) { const k = r * size + i; matrix[k]! *= normalization[i]!; length += matrix[k]! * matrix[k]!; }
