          const actual = model.pointAcceleration(p.body, p.point, acceleration).linear;
          for (let k = 0; k < 3; k++) state.motion.accelerationViolation = Math.max(state.motion.accelerationViolation, Math.abs(actual[k]! - p.curvature[k]!));
