import {contactTracking as experimental} from './contact-tracking.ts';
const sha=x=>createHash('sha256').update(x).digest('hex'),dir='.review/stand-up-replant/';
const source=deserialize(gunzipSync(fs.readFileSync('.review/stand-up-foot-first/selected.trace.gz'))),model=JSON.parse(fs.readFileSync('.review/stand-up-foot-transfer/reconstruction.json')).model;
assert.deepEqual(source.identity,model.identity);
const observation=source.rows[191].observation,detached=detachedDynamics(model);detached.read(observation);
assert.ok(observation.contacts.some(c=>c.segment==='foot.right'&&c.fixed!==null&&c.impulse>0));
const frames=new Map([...detached.built.segments].map(([name,s])=>['segment:'+name,s.body]));
const settings={maxPoints:64,gap:.005,minUpNormal:.9,pointSeparation:.002,liftOff:{accelerationTolerance:.1},normalResponseSeconds:.2,forceTolerance:1e-5,redistributionCost:1e-6,iterations:512,absoluteTolerance:1e-7,relativeTolerance:1e-6};
const radius=(frame,index)=>{const shape=detached.built.segments.get(frame.slice('segment:'.length)).rigid.shapes[index];return ['box','hull'].includes(shape.kind)?0:shape.radius.value;};
const records=[];
for(const [name,factory] of [['original',original],['experimental',experimental]])for(const release of [false,true]){
 const tracker=factory(detached.physics,frames,model.channels.length,settings,128,{dt:1/120,radius});
 const command={joints:[],frames:[],grips:[],supports:release?[{frame:{kind:'segment',name:'foot.right'},mode:'free'}]:[]};
 const rows=tracker.read(command,new Set(),false,.002),separation=tracker.releasedRows();
 const floor=separation.filter(r=>r.id.startsWith('segment:foot.right:'));
 if(release)assert.equal(floor.length>0,name==='experimental');else assert.equal(floor.length,0);
 for(const row of floor){assert.ok(Number.isFinite(row.target));assert.deepEqual(row.row[0].linear,[0,1,0]);}
 records.push({name,release,stickingRows:rows.length,separation:separation.map(r=>({id:r.id,target:r.target,point:r.row[0].point,normal:r.row[0].linear}))});
}
assert.deepEqual(records[0].separation,records[2].separation);assert.equal(records[0].stickingRows,records[2].stickingRows);
const report={sourceTraceSha256:source.traceSha256,sourceStep:192,observationSha256:sha(JSON.stringify(observation)),records,sourceSha256:sha(fs.readFileSync(dir+'contact-tracking.ts'))};
fs.writeFileSync(dir+'contact-probe.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));

