.review/stand-up-foot-geometry/surface-p.text:
// Box centres use body coordinates; their dimensions already use segment-local axes.
export function surfacePoints(segment,correctBoxes){
 const local=point=>[segment.frame.x,segment.frame.y,segment.frame.z].map(axis=>axis.reduce((sum,v,i)=>sum+v*(point[i]-segment.frame.origin[i]),0)),points=[];
 for(const shape of segment.rigid.shapes){
  if(shape.kind==='hull')points.push(...shape.points.map(p=>local(p.value)));
  else if(shape.kind==='box'){
   const centre=local(shape.centre.value);
   for(const x of [-1,1])for(const y of [-1,1])for(const z of [-1,1])points.push(correctBoxes?centre.map((v,i)=>v+[x,y,z][i]*shape.size.value[i]/2):local(shape.centre.value.map((v,i)=>v+[x,y,z][i]*shape.size.value[i]/2)));
  }else throw Error('surface placement requires a hull or box');
 }
 return points;
}

