import {Vector3} from '@babylonjs/core/Maths/math.vector.js';

// Equal and opposite normal rows describe only observed, loaded contacts inside the prediction body.
export function selfRows(model,detached,o,seconds){
 const parts=new Map(o.segments.map(s=>[s.name,s])),rows=[],seen=new Set();
 const velocity=(name,at)=>{const s=parts.get(name);return Vector3.Cross(new Vector3(...s.spin),new Vector3(...at).subtractInPlace(new Vector3(...s.centre))).addInPlaceFromFloats(...s.velocity);};
 for(const contact of o.contacts){
  if(contact.fixed!==null||contact.impulse<=0||!contact.other)continue;
  const other=model.segments.find(s=>contact.other===o.model+'.'+s.name)?.name;
  if(!other||contact.segment>=other)continue;
  for(const pair of contact.pairs){
   if(!(pair.impulse>0))continue;
   const id=`self:${contact.segment}:${other}:${pair.mine}:${pair.theirs}`;
   if(seen.has(id))continue;seen.add(id);
   const normal=new Vector3(...pair.normal).scaleInPlace(-1).normalize(),rate=Vector3.Dot(normal,velocity(contact.segment,pair.point).subtractInPlace(velocity(other,pair.point)));
   rows.push({id,gap:0,rate,target:-rate/seconds,
    row:[{body:detached.built.segments.get(contact.segment).body,point:pair.point,linear:normal.asArray(),angular:[0,0,0]},
     {body:detached.built.segments.get(other).body,point:pair.point,linear:normal.scale(-1).asArray(),angular:[0,0,0]}]});
  }
 }
 if(rows.length>64)throw Error('self-contact prediction capacity exceeded');
 return rows;
}

