import {pathPolicy as referencePolicy} from './reference-policy.mjs';
import {detachedDynamics} from '../../research/stand-up-detached-dynamics.mjs';
import {coupledDynamics} from '../../src/core/build/coupled-dynamics.ts';
import {linearWork,solveLinearTo} from '../../src/core/math/flat.ts';
import {Quaternion,Vector3} from '@babylonjs/core/Maths/math.vector.js';

export function pathPolicy({channels,reference,parameters:p,model}){
 const base=referencePolicy({channels,reference,parameters:p}),detached=detachedDynamics(model),dynamics=coupledDynamics(detached.built,model.gravity);
 const n=channels.length,H=new Float64Array(n*n),rhs=new Float64Array(n),answer=new Float64Array(n),work=linearWork(n);
 const allowed=channels.map(c=>/^(hip|knee|ankle)/.test(c.name));
 const state={phase:0,base:base.state,anchors:{},active:false,correction:channels.map(()=>0),error:0};
 const policy=o=>{
  const action=base(o);state.phase=base.state.phase;state.active=false;state.correction.fill(0);state.error=0;
  const age=o.time-base.state.started;
  if(action.kind!=='muscles'||!(p.supportGain>0)||age<(p.after??3.8)||age>(p.until??4.45))return action;
  detached.read(o);dynamics.update();H.fill(0);rhs.fill(0);
  for(const name of ['foot.left','foot.right']){
   const s=o.segments.find(s=>s.name===name),rotation=new Quaternion(...s.rotation),inverse=Quaternion.Inverse(rotation);
   if(!state.anchors[name]){
    const patches=o.contacts.filter(c=>c.segment===name&&c.fixed!==null&&c.impulse>0&&Math.abs(c.normal[1])>=.9)
     .flatMap(c=>(c.patch??[]).filter(p=>p.distance<=0&&Math.abs(p.normal[1])>=.9));
    if(patches.length)state.anchors[name]=patches.map(p=>({world:[...p.point],local:new Vector3(...p.point.map((v,i)=>v-s.position[i])).applyRotationQuaternionToRef(inverse,new Vector3()).asArray()}));
   }
   const anchors=state.anchors[name]??[],body=detached.built.segments.get(name).body;
   for(const anchor of anchors){
    const point=new Vector3(...anchor.local).applyRotationQuaternionToRef(rotation,new Vector3()).asArray().map((v,i)=>v+s.position[i]);
    const arm=point.map((v,i)=>v-s.centre[i]),spin=s.spin;
    const velocity=[s.velocity[0]+spin[1]*arm[2]-spin[2]*arm[1],s.velocity[1]+spin[2]*arm[0]-spin[0]*arm[2],s.velocity[2]+spin[0]*arm[1]-spin[1]*arm[0]];
    for(let axis=0;axis<3;axis++){
     const linear=[0,0,0];linear[axis]=1;
     const row=dynamics.motionRow([{body,point,linear,angular:[0,0,0]}]).coefficients.slice(6).map((v,i)=>allowed[i]?v:0);
     const error=anchor.world[axis]-point[axis],target=p.supportGain*((p.positionGain??8)*error-(p.velocityGain??1)*velocity[axis]);
     state.error=Math.max(state.error,Math.abs(error));
     for(let i=0;i<n;i++){rhs[i]+=row[i]*target/anchors.length;for(let j=0;j<n;j++)H[i*n+j]+=row[i]*row[j]/anchors.length;}
    }
   }
  }
  for(let i=0;i<n;i++)H[i*n+i]+=p.ridge??.01;
  solveLinearTo(work,H,rhs,n,answer);state.active=true;
  state.correction=Array.from(answer,v=>Math.max(-(p.cap??1),Math.min(p.cap??1,v)));
  return {...action,velocity:action.velocity.map((v,i)=>typeof v==='number'?v+state.correction[i]:v)};
 };
 policy.state=state;return policy;
}

