 const report={codeSha256:createHash('sha256').update(fs.readFileSync(new URL(import.meta.url))).digest('hex'),equalPhysicalObservationThroughRow:721,changes};
 fs.writeFileSync(dir+'handover-state.json',JSON.stringify(report,null,2));
 console.log(JSON.stringify({changes:changes.length,before:changes.filter(x=>x.path.startsWith('721.')).map(x=>({path:x.path,original:x.original,commands:x.commands})).slice(0,45)},null,2));
