import {pathPolicy as motionPolicy} from './motion-policy.mjs';
export function pathPolicy(args){
 const base=motionPolicy(args),p=args.parameters,state={phase:0,started:null,base:base.state,hostStep:false};
 const policy=o=>{
  state.started??=o.time;
  const action=base(o);state.phase=base.state.phase;
  const step=Math.round((o.time-state.started)*120);
  state.hostStep=(p.hostPulses??[]).some(pulse=>step>=pulse.start&&step<pulse.start+pulse.steps);
  return state.hostStep?{kind:'host'}:action;
 };
 policy.state=state;return policy;
}

