import {pathPolicy as recordedPath} from '../../research/stand-up-path-policy.mjs';
import {detachedDynamics} from '../../research/stand-up-detached-dynamics.mjs';
import {coupledDynamics} from '../../src/core/build/coupled-dynamics.ts';
import {linearWork,solveLinearTo} from '../../src/core/math/flat.ts';

export function pathPolicy({channels,reference,parameters:p,model}) {
 const base=recordedPath({channels,reference,parameters:p}),detached=detachedDynamics(model);
 const terminal=p.terminal?recordedPath({channels,reference:{...reference,frames:[reference.frames.at(-1)],release:0},
  parameters:{...p.terminal,startPhase:0,release:0,window:0,terminalAfter:0,releaseHeight:0,releaseUp:-1}}):null;
 const dynamics=coupledDynamics(detached.built,model.gravity),n=channels.length;
 const allowed=channels.map(c=>p.group==='arms'?/^(shoulder|elbow|wrist)/.test(c.name):p.group==='upper'?/^(neck|thoracic|lumbar|shoulder|elbow|wrist)/.test(c.name):true);
 const H=new Float64Array(n*n),rhs=new Float64Array(n),x=new Float64Array(n),work=linearWork(n);
 const state={phase:0,base:base.state,terminal:terminal?.state??null,correction:channels.map(()=>0),active:false};
 const policy=o=>{
  let action=base(o);state.phase=base.state.phase;state.active=false;state.correction.fill(0);
  if(terminal&&o.time-base.state.started>=(p.after??5.4))action=terminal(o);
  if(action.kind!=='muscles'||!(p.damp>0)||o.time-base.state.started<(p.after??5.4)
    || o.time-base.state.started>(p.until??Infinity))return action;
  detached.read(o);dynamics.update();H.fill(0);rhs.fill(0);
  const names=p.targets??['hand.right','hand.left','head'];
  for(const name of names){
   const s=o.segments.find(s=>s.name===name),body=detached.built.segments.get(name).body;
   for(let axis=0;axis<3;axis++){
    const linear=[0,0,0];linear[axis]=1;
    const row=dynamics.motionRow([{body,point:s.centre,linear,angular:[0,0,0]}]).coefficients.slice(6).map((v,i)=>allowed[i]?v:0);
    for(let i=0;i<n;i++){rhs[i]-=row[i]*s.velocity[axis]*p.damp;for(let j=0;j<n;j++)H[i*n+j]+=row[i]*row[j];}
   }
  }
  for(let i=0;i<n;i++)H[i*n+i]+=p.ridge??.01;
  solveLinearTo(work,H,rhs,n,x);state.active=true;
  state.correction=Array.from(x,v=>Math.max(-(p.cap??.5),Math.min(p.cap??.5,v)));
  return {...action,velocity:action.velocity.map((v,i)=>typeof v==='number'?v+state.correction[i]:v)};
 };
 policy.state=state;return policy;
}

