import {pathPolicy as motionPolicy} from './motion-policy.mjs';
import {detachedDynamics} from '../../research/stand-up-detached-dynamics.mjs';
import {coupledDynamics} from '../../src/core/build/coupled-dynamics.ts';
import {linearWork,solveLinearTo} from '../../src/core/math/flat.ts';
import {withinSupport} from '../../.tools/stand-up-frozen/src/core/control/support.ts';
import {Vector3} from '@babylonjs/core/Maths/math.vector.js';

/** Bounded trunk muscle correction toward the measured loaded-foot support region. */
export function pathPolicy(args){
 const base=motionPolicy(args),p=args.parameters,{model,channels}=args;
 const detached=detachedDynamics(model),dynamics=coupledDynamics(detached.built,model.gravity);
 const n=channels.length,H=new Float64Array(n*n),rhs=new Float64Array(n),x=new Float64Array(n),work=linearWork(n);
 const mass=model.segments.reduce((s,b)=>s+b.mass,0),allowed=channels.map(c=>/^(thoracic|lumbar)/.test(c.name));
 const state={phase:0,started:null,base:base.state,active:false,offset:[0,0],correction:channels.map(()=>0)};
 const policy=o=>{
  state.started??=o.time;const action=base(o);state.phase=base.state.phase;state.active=false;state.correction.fill(0);state.offset.fill(0);
  const age=o.time-state.started;
  if(action.kind!=='muscles'||!(p.supportGain>0)||age<p.supportAfter||age>p.supportUntil)return action;
  const soles=['foot.left','foot.right'].map(segment=>({corners:o.contacts.filter(c=>c.segment===segment&&c.fixed!==null&&c.impulse>0&&Math.abs(c.normal[1])>=.9)
   .flatMap(c=>(c.patch??[]).filter(q=>q.distance<=0&&Math.abs(q.normal[1])>=.9).map(q=>new Vector3(...q.point)))}));
  if(soles.some(s=>!s.corners.length))return action;
  const nearest=withinSupport(soles,o.centre[0],o.centre[2]);state.offset=[nearest[0]-o.centre[0],nearest[1]-o.centre[2]];
  detached.read(o);dynamics.update();H.fill(0);rhs.fill(0);
  for(const [k,axis] of [0,2].entries()){
   const entries=model.segments.map(s=>{const linear=[0,0,0];linear[axis]=s.mass/mass;return {body:detached.built.segments.get(s.name).body,
    point:o.segments.find(q=>q.name===s.name).centre,linear,angular:[0,0,0]};});
   const row=dynamics.motionRow(entries).coefficients.slice(6).map((v,i)=>allowed[i]?v:0);
   for(let i=0;i<n;i++){rhs[i]+=row[i]*state.offset[k]*p.supportGain;for(let j=0;j<n;j++)H[i*n+j]+=row[i]*row[j];}
  }
  for(let i=0;i<n;i++)H[i*n+i]+=.0001;
  solveLinearTo(work,H,rhs,n,x);state.active=true;
  state.correction=Array.from(x,v=>Math.max(-.15,Math.min(.15,v)));
  return {...action,velocity:action.velocity.map((v,i)=>typeof v==='number'?v+state.correction[i]:v)};
 };
 policy.state=state;return policy;
}

